# Written by Anyserve. Changes here are replaced on reconfigure.
{
  hostname: {{json .Settings.hostname}}
  bind: "0.0.0.0"
  port: 8536
  tls_enabled: {{truefalse .Settings.https}}
  database: {
    host: "postgres"
    port: 5432
    user: "lemmy"
    password: {{json .Settings.postgres_password}}
    database: "lemmy"
  }
  pictrs: {
    url: "http://pictrs:8080/"
    api_key: {{json .Settings.pictrs_api_key}}
  }
  # Used only on the first start, to create the admin and the site.
  setup: {
    admin_username: {{json .Settings.admin_username}}
    admin_password: {{json .Settings.admin_password}}
    site_name: {{json .Settings.site_name}}
    {{if .Settings.admin_email}}admin_email: {{json .Settings.admin_email}}{{end}}
  }
}

# Written by Anyserve. Changes here are replaced on reconfigure.
pid /tmp/nginx.pid;
worker_processes auto;
events {}

http {
  # The unprivileged image can only write under /tmp.
  client_body_temp_path /tmp/client_temp;
  proxy_temp_path /tmp/proxy_temp;
  fastcgi_temp_path /tmp/fastcgi_temp;
  uwsgi_temp_path /tmp/uwsgi_temp;
  scgi_temp_path /tmp/scgi_temp;

  # Look containers up through Docker's DNS on every request, so a
  # restarted container is found again without restarting nginx.
  resolver 127.0.0.11 valid=10s ipv6=off;

  # Lemmy's backend answers writes and ActivityPub lookups from other
  # servers; the web UI answers people's browsers.
  map $request_method $anyserve_write {
    GET 0;
    HEAD 0;
    default 1;
  }
  map $http_accept $anyserve_activitypub {
    default 0;
    "~application/(activity|ld)\+json" 1;
  }
  map "$anyserve_write$anyserve_activitypub" $anyserve_upstream {
    "00" "http://lemmy-ui:1234";
    default "http://lemmy:8536";
  }

  server {
    listen 8080;
    server_tokens off;
    client_max_body_size 20M;

    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;

    set $anyserve_backend "http://lemmy:8536";
    set $anyserve_ui "http://lemmy-ui:1234";

    location / {
      proxy_pass $anyserve_upstream;
    }
    # The API, images, feeds and discovery files always come from the
    # backend, except security.txt, which the UI serves.
    location ~ ^/(api|pictrs|feeds|nodeinfo|\.well-known|version|sitemap\.xml)(/|$) {
      proxy_pass $anyserve_backend;
    }
    location = /.well-known/security.txt {
      proxy_pass $anyserve_ui;
    }
  }
}

// Written by Anyserve. Changes here are replaced on reconfigure;
// put your own settings in q4base/server.cfg instead.
set si_name "{{.Settings.server_name}}"
set si_gameType "{{.Settings.game_type}}"
set si_maxPlayers {{.Settings.max_players}}
set si_map "{{.Settings.map}}"
set net_serverDedicated 1
set si_usePass {{if .Settings.password}}1{{else}}0{{end}}
set g_password "{{.Settings.password}}"
set net_serverRemoteConsolePassword "{{.Settings.rcon_password}}"
exec server.cfg

