# use `anyserve config` to change settings instead.
world={{.Dir}}/worlds/{{.Settings.world_name}}.wld
worldpath={{.Dir}}/worlds
worldname={{.Settings.world_name}}
autocreate={{.Settings.world_size}}
difficulty={{.Settings.difficulty}}
{{if .Settings.seed}}seed={{.Settings.seed}}
{{end}}maxplayers={{.Settings.max_players}}
port={{.Ports.game}}
{{if .Settings.password}}password={{.Settings.password}}
{{end}}motd={{.Settings.motd}}
secure=1
upnp=0
banlist={{.Dir}}/banlist.txt
